INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m1', 'ai101', 1, 'What is AI?', 'A working mental model: what an LLM actually does, the vocabulary, why data decides everything, and a delegation heuristic you can carry under pressure.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m2', 'ai101', 2, 'Choosing the tool for the task', 'Chat assistants, copilots, and the AI already embedded in your HR stack — what each is actually for, and how to tell a language model from a scoring engine before you rely on either.', 'locked', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m3', 'ai101', 3, 'What it costs and how it scales', 'Tokens, context windows, and pricing — enough of the economics to size a use case, read a vendor quote, and know when a bigger model is worth it.', 'locked', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m4', 'ai101', 4, 'Working with your documents and data', 'Attachments, long documents, and sensitive material: getting your world into the model''s view without crowding out the question — or crossing a line your legal team hasn''t cleared.', 'locked', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m5', 'ai101', 5, 'Prompting as briefing', 'Role, task, context, format. Prompting as briefing a capable stranger — and iteration as the keystone behavior that separates fluent users from frustrated ones.', 'locked', 35, '["ai101-m1"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m6', 'ai101', 6, 'When it''s confidently wrong', 'Hallucination in depth: why fluent output deserves more scrutiny, not less, and the verification habits that keep a fabricated citation out of a document with someone''s name on it.', 'locked', 30, '["ai101-m1"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m7', 'ai101', 7, 'The lines that don''t move', 'Bias, adverse impact, and decisions about people. Where AI assists, where it must stop, and how to say so in a way your organization will actually follow.', 'locked', 30, '["ai101-m6"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m8', 'ai101', 8, 'What you own', 'Data agreements, disclosure, and accountability. What you''re responsible for when AI touched the work — and the policy questions to settle before someone asks.', 'locked', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m1', 'ai201', 1, 'From one-offs to workflows', 'The workflow lens: five parts every repeatable workflow has, the audit that finds your candidates, the selection rules — and the capstone''s first stage: pick your build and spec it.', 'open', 30, NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-brief', 'ai101-m1', 10, 'prose', 'stable', '## Why this module exists

You almost certainly already use AI. You''ve probably asked something to tidy up a job description, turn a page of interview scrawl into a debrief a hiring manager can read, soften a rejection email, or explain a benefits provision in language an employee will actually understand. So opening a course with "what is AI?" is a strange move. The answer is on your screen already.

But there is a difference between using this technology and understanding what happens when you use it, and most people skip the second part. That skip is where the Risk-stage problems come from. People without a working mental model tend to land in one of two places. Some treat it as a search engine that returns true facts — it is not, and it does not. Others treat it as a colleague with intentions, judgment, and a stake in the outcome — it has none of those, not in the way you mean. Both framings will get you in trouble, in different ways and on different timelines.

There''s a reason to care about this more in People work than in most functions. In sales, using AI carelessly produces a weak email. In People, it can produce a document that shapes someone''s livelihood — a performance write-up, a policy interpretation, a screening decision, an investigation summary — and it can produce that document fluently, confidently, and wrong. The gap between how good the output *sounds* and how good it *is* is exactly the gap this module exists to close.

This module gives you a third framing: accurate enough to be useful, simple enough to carry around under pressure. No mathematics, no philosophy, no diagrams of neural networks. Just a working account of what these systems do, where they come from, and what that means for how you use them.

**A note on your two roles.** As a People leader you will be asked to do two different things with AI: use it well in your own work, and eventually help other functions adopt it. Those are different jobs and they need different preparation. You cannot credibly lead a change you can''t perform, so this course is about the first one. The second gets its own course, later.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-objectives', 'ai101-m1', 20, 'callout', 'stable', '### Learning objectives

By the end of this module you should be able to:

1. Explain, in plain language, what people mean by "AI" today — and what they don''t.
2. Describe what a large language model actually does when you send it a message.
3. Recognize and use the working vocabulary: model, prompt, context window, token, knowledge cutoff, hallucination, agent.
4. Articulate why data — both what the model was trained on and what you hand it — determines the quality of what you get back.
5. Predict, before you begin a task, whether AI is likely to do it well.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-intro', 'ai101-m1', 30, 'prose', 'stable', '## Lesson 1 · What we mean when we say "AI"

The word is doing far too much work. People use it for the résumé screener in the ATS, the sentiment scoring on your engagement survey, ChatGPT, the anomaly flag in payroll, and the menacing robot from a film — often in the same meeting. That''s part of why two reasonable people can have wildly different reactions to "we should use more AI." They''re not discussing the same thing.

Here''s the cut that clears it up. **"AI" is a category, not a technology.** Inside that category sit many different systems built in different ways for different purposes. The kind currently reshaping knowledge work — and the kind this course is mostly about — is a specific type called a **large language model**, or LLM. When a colleague says "I used AI to write this," they almost always mean they used an LLM.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-lineup', 'ai101-m1', 40, 'prose', 'volatile', 'The LLMs you''ll encounter most: Claude, from Anthropic. ChatGPT, from OpenAI, built on the GPT family. Gemini, from Google. Those are the consumer-facing names; underneath, they''re the same general kind of system — software trained on an enormous quantity of text that reads and produces human-like language.', '["model-lineup"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-hrstack', 'ai101-m1', 50, 'prose', 'stable', '### The part that matters specifically for People work

Much of the "AI" already sitting in your HR technology stack is **not** an LLM. Résumé matching and ranking, candidate scoring, attrition risk models, engagement sentiment classification, payroll anomaly detection, scheduling optimization — most of these are older machine-learning techniques doing statistical classification or scoring. Some vendors have since layered an LLM on top for the chat interface while the underlying scoring engine remains what it always was.

This distinction is not pedantry, for three reasons:

- **It changes what questions to ask a vendor.** "Is this a language model or a scoring model?" gets you further than "is this AI?", which every vendor now answers yes to.
- **It changes the failure mode.** A scoring model fails by being systematically biased against a group. A language model fails by fabricating. Those need different controls.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-regulatory', 'ai101-m1', 60, 'prose', 'volatile', '- **It changes your regulatory exposure.** Regulation in this area tends to attach to *automated decision-making about people* rather than to a technology label. A scoring model that ranks candidates is squarely in scope under rules like NYC''s Local Law 144 and the EU AI Act''s treatment of employment as high-risk. An LLM you use to redraft a job posting generally isn''t. Confusing the two means you either over-comply on harmless uses or under-comply on the ones that count. *Verify current specifics with counsel — this area moves.*', '["employment-regulation","eu-ai-act"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-close', 'ai101-m1', 65, 'prose', 'stable', 'So: when this course says "AI" without qualification, it means a large language model. Software that takes text in and produces text out, using patterns learned from a very large quantity of text it was trained on.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-try', 'ai101-m1', 70, 'try_this', 'stable', '### Try this — 2 minutes

1. List every place you used AI at work last week. Be specific: not "ChatGPT," but "I had it rewrite the internal comms note about the benefits change."
2. For each one, ask: was that an LLM, or was it a scoring or matching feature inside a tool I already use?
3. Then look at your ATS or HRIS. Find one feature marketed as AI and decide which kind it is.

You won''t be certain on all of them. That uncertainty is useful information — it tells you where you''d have to ask a vendor a direct question.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l1-sort', 'ai101-m1', 80, 'exercise', 'stable', '{"type":"sorting","title":"Calibration exercise — Where does AI actually help?","intro":"Ten minutes. This is the most important exercise in the module.\n\nBelow are fifteen tasks a People team might plausibly hand to an LLM. Sort each into **does this well**, **does this partly — needs verification**, or **does this badly — don''t**.\n\nNothing reveals until all fifteen are committed — an unscored guess teaches nothing."}', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l2-mechanism', 'ai101-m1', 90, 'prose', 'stable', '## Lesson 2 · What an LLM actually does, in plain English

The mechanism reduces to one sentence:

> **A large language model is software that, given some text, predicts what text should come next — one small piece at a time.**

Everything else is detail. But the detail is where the practical consequences live, so it''s worth two minutes.

### The training step

Before you type anything, the model has been trained. Training means it was shown an enormous quantity of text — books, articles, websites, code, transcripts, forums — and learned the statistical patterns of how language works. Not memorized. Learned. It picked up that "we regret to inform you that your application" is very likely followed by something other than "congratulations." It picked up grammar, register, tone, structure, factual associations, and a few thousand other regularities, all from patterns in text.

That training happened before you arrived. When you open the tool, the model is already finished. You are not teaching it anything during your conversation, and Lesson 4 explains why that matters more than it sounds like it should.

### The prediction step

Now you type. The model takes your message plus everything else in the conversation and asks one narrow question: *given everything I''ve seen so far, what''s the most likely next piece of text?* It picks a piece, appends it, and asks again. And again, until it stops.

It is not drafting a complete answer and then writing it out. It is not retrieving an answer from a database. It is generating text one fragment at a time, where each fragment is the most probable continuation of everything before it.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l2-try', 'ai101-m1', 100, 'try_this', 'stable', '### Try this — 3 minutes

1. Open your AI tool.
2. Send exactly: *"Tell me a short, surprising fact about octopuses, then explain how you know it."*
3. Read the answer.
4. Follow up: *"How did you generate that? Walk me through what actually happened, step by step."*

You''ll get the model''s own account of itself. Notice the vocabulary — probability, training data, patterns. Notice what it never says: *"I looked it up."* *"I checked a source."* Because neither happened.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l2-frustrations', 'ai101-m1', 110, 'prose', 'stable', '### Why this explains almost everything that will frustrate you

**Why it sounds confident about wrong things.** The model isn''t checking facts as it writes; it''s producing statistically likely text. Sometimes statistically likely text is also true. Sometimes it isn''t. In human writing, confidence and correctness are loosely coupled — someone who sounds certain usually has reason to be. That coupling does not exist here. M6 is entirely about this.

**Why the same prompt gives different answers.** There''s a small amount of randomness in how each next piece gets chosen. Without it, every response would be identical and mechanical. With it, asking twice gives you two drafts. That''s not a malfunction — it''s why re-running a prompt is a legitimate technique rather than a sign something broke.

**Why context changes everything.** Because prediction runs on everything the model has been given, more relevant material means better predictions. A vague prompt leaves the model predicting from almost nothing. A prompt carrying role, task, context, and format narrows the prediction toward what you actually wanted. M5 covers this properly.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l2-memory', 'ai101-m1', 120, 'prose', 'volatile', '**Why it doesn''t remember you.** Each conversation typically starts fresh. The model has no memory across sessions unless something was specifically built to give it one. Memory features have become common across the major tools, but they vary in what they retain and for how long, and the default is often off. Never assume; check what your specific tool does.', '["memory-features"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l2-honest', 'ai101-m1', 130, 'prose', 'stable', '### The honest part: nobody fully understands the inside

Even the people who build these systems don''t fully understand how they work internally. Training produces a model with billions of parameters that encode the learned patterns, and those parameters aren''t human-readable. Anthropic has published interpretability research — techniques for tracing what happens inside a model as it responds — precisely because the internals aren''t otherwise visible, including to them.

What that research has surfaced is genuinely interesting. There''s evidence models do more than blind word-by-word prediction in some cases: planning ahead toward a rhyming word before starting a line, for instance, or representing concepts in a shared space that spans languages. There''s also evidence that when a model explains its reasoning, the explanation doesn''t always match what actually happened internally.

You don''t need to retain any of that. It''s here because it pushes back on both of the confident positions you''ll hear in meetings — *"it''s just autocomplete"* (mechanically defensible, underestimates what falls out of the mechanism) and *"it genuinely thinks"* (wrong in a different direction). The useful stance sits between: a powerful pattern-matcher trained on a vast amount of human text, which often produces startlingly good output and has failure modes worth building habits around.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l3-vocab-a', 'ai101-m1', 140, 'prose', 'stable', '## Lesson 3 · The vocabulary, demystified

You''ll keep hearing these. Don''t memorize them — read through once and notice the shape of each. They recur throughout the course.

**Model.** The trained system itself. When someone says "the model did something strange," they mean the underlying AI, not the website they used to reach it. Models come in different sizes; larger ones are generally more capable, slower, and more expensive to run.

**Prompt.** What you send — your text, plus any instructions, context, or attached material. Your prompt is the single largest lever you have on output quality. M5 is entirely about this.

**Context window.** How much text the model can hold in view at once when responding: your message, the conversation so far, and anything attached. It''s finite. When it fills, earlier material effectively drops out of view — which is why long conversations start to feel like the model forgot something, and why pasting in a 90-page handbook can crowd out your actual question.

**Token.** The unit models process text in — roughly a word or word-fragment. Mostly this matters for two reasons: context windows are measured in tokens, and pricing is usually per token. M3 covers the economics.

**Training data.** The text the model learned from. It shapes everything: what the model handles well, what it fumbles, what registers it can write in, and what biases it carries.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l3-cutoff', 'ai101-m1', 150, 'prose', 'volatile', '**Knowledge cutoff.** The date past which the model wasn''t trained on new information. Most current tools pair the model with web search to compensate, but the underlying model still has a cutoff. It''s why asking about yesterday''s news, without search enabled, produces something fluent and useless.', '["knowledge-cutoff","search-features"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l3-vocab-b', 'ai101-m1', 160, 'prose', 'stable', '**Hallucination.** When a model produces something confident, plausible, and wrong or invented. The single most important failure mode to understand, and the one with the sharpest consequences in People work. M6 is devoted to it.

**Agent.** A model configured to take actions rather than only respond — browsing, sending, updating a record, running code — within whatever permissions it''s been given. You don''t need to work with agents at this level. Just know the word means *an AI system that does things*, not one that only talks.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l3-multimodal', 'ai101-m1', 170, 'prose', 'volatile', '**Multimodal.** Models that handle more than text — images, audio, documents. Current frontier models are multimodal; you can paste a screenshot of an org chart or attach a PDF policy and ask questions about it. Same mechanics underneath, wider set of inputs.', '["multimodal-capabilities"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l3-try', 'ai101-m1', 180, 'try_this', 'stable', '### Try this — 3 minutes

Open the product page of one HR tool your team uses that advertises AI features. Read the claims and answer three questions:

1. Is this a language model, a scoring or matching model, or both?
2. What data was it trained on — theirs, yours, or unstated?
3. Does it make or influence a decision about a person?

If you can''t answer all three from the page, you''ve just written your first three vendor questions. That''s the exercise working.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-training', 'ai101-m1', 190, 'prose', 'stable', '## Lesson 4 · Why data is the whole game

If one thing survives from this module, make it this: **AI is a data problem before it is anything else.** What you get out is determined, almost entirely, by two things — what the model was trained on, and what you hand it in the moment.

### Training data shapes the model

The model only handles well what it saw patterns for. Well-represented topics get handled well. Sparse ones get hedging, vagueness, or invention.

Practical consequences:

- A model trained mostly on English performs better in English, even when it produces other languages competently.
- A model trained on public text has never seen your handbook, your HRIS, your comp bands, your Slack, your investigation files, or your board deck. It cannot draw on what it never saw.
- **All training data carries bias, and models reproduce it.** In most functions that''s an abstract concern. In People work it is not. A model asked to evaluate, rank, or characterize people can reproduce patterns present in its training text — and in an employment context, that is the mechanism by which adverse impact happens. This is why the delegation heuristic ends with *"it must not make decisions about people."*

The habit to build: before asking, form a rough view of whether this is the kind of thing the model would have seen a great deal of. *"Rewrite this clunky paragraph"* — enormous quantities of training data. *"What''s our policy on carryover PTO"* — none whatsoever. The first is squarely in the model''s competence. The second, asked cold, produces something fluent, confident, and made up.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-recency', 'ai101-m1', 200, 'prose', 'volatile', 'One more practical consequence: a model trained through a given date is unreliable about anything after it, unless you supply fresh information or search is enabled.', '["knowledge-cutoff"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-supply', 'ai101-m1', 210, 'prose', 'stable', '### The data you supply

The second kind is what you give it — your prompt, your attachments, the context you establish. Because the model knows only its training plus what''s in the current conversation, the material you supply is your only channel for getting your specific world into the picture.

Ask for a summary of your engagement survey results without pasting the results, and the model will produce a survey summary. A generic, plausible, entirely fictional one. Paste the actual comments and you get real analysis. Same model, same prompt structure, completely different output — because the data changed.

This is why prompting is far more about **information** than about clever phrasing. The wording matters, and M5 will make you better at it, but wording is downstream of whether the model has what it needs.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-paste', 'ai101-m1', 220, 'prose', 'stable', '### A note on what you paste

People data is the most sensitive material in most organizations, which makes "what can I put in here" a sharper question for you than for almost any other function. Employee records, health information, investigation notes, compensation data, and anything identifying a named individual sit at the top of that gradient.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-agreements', 'ai101-m1', 230, 'prose', 'volatile', 'The answer depends entirely on which tool you''re using and under what agreement — an enterprise deployment with a data processing agreement is a different situation from a personal account on a consumer tier. Find out which one you''re in before you paste, not after. Your security or legal team has this answer. If nobody does, that gap is itself worth raising.', '["data-agreements"]', '2026-08-04');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-close', 'ai101-m1', 240, 'prose', 'stable', 'M8 returns to this when we discuss what you own. For now: data is what makes the system work, and the data you supply is the part you control.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-l4-try', 'ai101-m1', 250, 'try_this', 'stable', '### Try this — 3 minutes

1. Pick one thing you did last week that involved AI, or could have.
2. Ask: what did the model need to know that it couldn''t have known on its own?
3. If you didn''t supply that, what did it fill the gap with?

The question *"what does this model not know that I''d have to give it?"* is the single most useful habit in this course. It''s the seed of good prompting and the seed of good judgment about when not to bother.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-takeaways', 'ai101-m1', 260, 'takeaways', 'stable', '## Key takeaways

- **"AI" is a category.** The kind reshaping your work is a large language model. Much of the AI already in your HR stack is something else — usually a scoring or matching model — and the distinction changes the failure mode, the vendor questions, and the regulatory exposure.
- **An LLM predicts the next piece of text, one piece at a time,** based on everything it''s seen. It is not retrieving, not verifying, and not reasoning the way a person does — even when the output looks like reasoning.
- **Confidence and correctness are decoupled** in a way they aren''t in human writing. This is the root of hallucination and the reason fluent output deserves more scrutiny, not less.
- **The model has never seen your organization.** Not your handbook, your data, your history, or your decisions. Anything requiring that knowledge must be supplied by you or it will be invented.
- **All training data carries bias, and in People work that''s not abstract** — it''s the mechanism behind adverse impact.
- **The delegation heuristic:** AI does well when you supply the material and ask for transformation; badly when the task needs organizational knowledge it was never given; and it must not make decisions about people.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1-activity-link', 'ai101-m1', 270, 'exercise', 'stable', '{"type":"activity_link","title":"Applied activity — Testing the Edges","blurb":"Three short conversations with your AI tool, each built to expose a different property of the system, then a 250–350 word reflection. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.","estMinutes":"20–25"}', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-intro', 'ai101-m1-activity', 10, 'prose', 'stable', '## Applied activity — "Testing the Edges"

**Time:** 20–25 minutes · **Submit:** a record of three conversations plus a 250–350 word reflection · **Graded against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

Have three short conversations with your AI tool. Each is built to expose a different property of the system. Then write a short reflection on what you noticed.

This is not about getting good answers. It''s about watching the thing behave so you build real intuition for what it is.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-conv1', 'ai101-m1-activity', 20, 'prose', 'stable', '### Conversation 1 — Where it''s strong

Pick a subject you know well: an area of People practice you''ve worked in for years, a policy you wrote, a process you own. Ask a substantive question. Read the answer critically — you''re one of the few people who can actually judge it. Then ask one follow-up that pushes deeper.

*Notice:* What does it handle well? Where does it sound like it genuinely understands? Where does it produce something that reads correctly but that you know is thin?', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-conv2', 'ai101-m1-activity', 30, 'prose', 'stable', '### Conversation 2 — Where it might fabricate

**Predict first.** Before you send anything, write down: *how likely is it that this answer contains something invented?* Give a percentage — there''s a field for it below.

Then ask for something specific and hard to verify. Options that work:

- A statistic about employment practice with a source citation
- What a specific named regulation requires in a specific jurisdiction
- Details about a small organization you know well
- A quotation from a specific page of a specific book

Now check it. Actually check it — follow the citation, look up the regulation, verify the number.

*Record:* your prediction, what actually happened, and how far off you were.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-conv3', 'ai101-m1-activity', 40, 'prose', 'stable', '### Conversation 3 — Where it can''t know

Ask something about your own organization that the model was never given. Your parental leave provision. Why your last engagement survey moved. Which of your roles takes longest to fill.

Watch carefully. Does it refuse? Hedge? Ask you for context? Or does it produce something fluent, specific, and fabricated? Then paste in the actual material and ask again.

*Notice:* the difference between the two answers is the entire lesson of Lesson 4.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-reflection', 'ai101-m1-activity', 50, 'prose', 'stable', '### The reflection — 250–350 words

Address all of:

- One thing the model did better than you expected
- One thing it did worse
- Your calibration: what you predicted in Conversation 2, what happened, and which direction you were wrong in
- One habit you''ll change on Monday, stated concretely enough that someone could check whether you did it', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1a-rubric', 'ai101-m1-activity', 60, 'table', 'stable', '### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Engagement with all three conversations** | All three run, with actual transcripts or faithful accounts. Follow-ups asked. Real subject matter, not placeholder queries. |
| **Observation of mechanics** | The reflection connects what was observed to how the system works — prediction, training data, context — rather than only reporting what it said. |
| **Calibration** | A prediction was made *before* Conversation 2, compared honestly afterward, and the direction of error is named. Accuracy isn''t scored; honesty and specificity are. |
| **Practical insight** | The habit named is concrete, tied to actual work, and checkable. Not "I''ll be more careful." |', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1micro-core', 'ai101-m1-micro', 10, 'prose', 'stable', '## Module 1 in two minutes

**"AI" is a category, not a technology.** The kind reshaping your work is a large language model (LLM): software that, given some text, predicts what should come next — one small piece at a time. It is not searching, not looking things up, and not reasoning like a colleague, even when it sounds like one. Much of the "AI" already in your HR stack is something else entirely — a scoring or matching model — and the distinction changes the failure mode, the vendor questions, and the regulatory exposure.

**Confidence and correctness are decoupled.** The model produces statistically likely text. Sometimes likely is also true; sometimes it isn''t. In human writing, someone who sounds certain usually has reason to be — that coupling does not exist here. Fluent output deserves more scrutiny, not less, and in People work a fluent, wrong document can shape someone''s livelihood.

**The model has never seen your organization.** Not your handbook, your comp bands, your survey data, your investigation files. Anything that requires that knowledge must be supplied by you in the conversation — or it will be invented, fluently, with no signal that it''s invented.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1micro-heuristic', 'ai101-m1-micro', 20, 'callout', 'stable', '### The delegation heuristic

AI does well when you supply the material and ask for transformation. It does badly when the task needs organizational knowledge it was never given. And it must not make decisions about people — regardless of how good the output looks.', NULL, '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('m1micro-habit', 'ai101-m1-micro', 30, 'prose', 'stable', '**The one habit to build:** before any task, ask *"what does the model not know that I''d have to give it?"* That single question is the seed of good prompting and of good judgment about what to hand over at all.', NULL, '2026-07-28');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-sorting', 'ai101-m1', 'sorting', '{"buckets":[{"id":"well","label":"Does this well","hint":"Hand it over"},{"id":"partly","label":"Does this partly","hint":"Needs verification"},{"id":"badly","label":"Does this badly","hint":"Don''t"}],"tasks":[{"id":"t1","text":"Rewrite a job description to strip out jargon and inflated requirements","key":"well","reasoning":"You supply the JD; the model transforms it. Language transformation on material you provide is the center of its competence."},{"id":"t2","text":"Turn a page of your messy interview notes into a structured debrief","key":"well","reasoning":"Your notes in, structure out. The model never needs to know anything you didn''t hand it."},{"id":"t3","text":"Explain what happened to attrition in your Denver office last quarter","key":"badly","reasoning":"The model never saw your attrition data. It will answer anyway — fluently, and invented."},{"id":"t4","text":"Draft three versions of a candidate rejection email at different levels of warmth","key":"well","reasoning":"Tone variation on a well-understood format. It has seen thousands of these."},{"id":"t5","text":"Summarize the themes across 200 engagement survey free-text comments you paste in","key":"partly","reasoning":"Good at surfacing patterns, but it flattens minority views and will present a confident summary of the comments it weighted most. Read the raw comments too."},{"id":"t6","text":"Tell you which section of your employee handbook covers bereavement leave","key":"badly","reasoning":"It has never seen your handbook. It has seen thousands of others, so what it produces will read exactly like yours — and won''t be."},{"id":"t7","text":"Generate interview questions for a competency you describe in detail","key":"well","reasoning":"You describe the competency; it generates against your description. Supply the material, ask for transformation."},{"id":"t8","text":"Recommend the comp band for a new role","key":"badly","reasoning":"Your comp philosophy, your bands, your market data — none of it was in training. Any number it gives is a fabrication wearing a confident face."},{"id":"t9","text":"Rewrite a policy paragraph so a non-native English speaker can follow it","key":"well","reasoning":"Plain-language rewriting of supplied text. Squarely in competence."},{"id":"t10","text":"Explain, in general terms, what a statutory leave entitlement typically covers","key":"partly","reasoning":"Reasonable in the abstract, unreliable on your jurisdiction, your plan, or current specifics. Verify anything you''d act on."},{"id":"t11","text":"Decide whether an employee''s conduct warrants termination","key":"badly","reasoning":"This one isn''t about capability. It''s a decision about a person''s livelihood and it stays with a human, however good the output looks."},{"id":"t12","text":"Draft a performance improvement plan from notes you supply","key":"partly","reasoning":"Structure and language, yes; the judgment about whether a PIP is warranted, never."},{"id":"t13","text":"Tell you what your CEO said at last month''s all-hands","key":"badly","reasoning":"It wasn''t in the room and the transcript wasn''t in its training. It will produce plausible executive remarks that nobody gave."},{"id":"t14","text":"Produce a plain-language FAQ from a benefits summary you paste in","key":"well","reasoning":"Pasted source, transformed format. The model has everything it needs because you gave it everything it needs."},{"id":"t15","text":"Identify which of your open roles is hardest to fill","key":"badly","reasoning":"Your requisition data never reached it. Same failure as the attrition question: a confident answer built on nothing."}],"pattern":"AI does well when you supply the material and ask for transformation. It does badly when the task needs organizational knowledge it was never given. And it must not make decisions about people.","postscript":"If you missed several, look at which kind you missed. Over-assigning to \"does this well\" means you''re likely to ship something fabricated. Over-assigning to \"does this badly\" means you''re leaving real leverage on the table. Both are calibration errors. Neither is a character flaw. Both are fixable, and the next seven modules are how."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-rubric', 'ai101-m1', 'rubric', '{"promptVersion":"m1-testing-the-edges-v1","moduleId":"ai101-m1","minWords":250,"maxWords":350,"dimensions":[{"name":"Engagement with all three conversations","criteria":"All three run, with actual transcripts or faithful accounts. Follow-ups asked. Real subject matter, not placeholder queries."},{"name":"Observation of mechanics","criteria":"The reflection connects what was observed to how the system works — prediction, training data, context — rather than only reporting what it said."},{"name":"Calibration","criteria":"A prediction was made before Conversation 2, compared honestly afterward, and the direction of error is named. Accuracy isn''t scored; honesty and specificity are."},{"name":"Practical insight","criteria":"The habit named is concrete, tied to actual work, and checkable. Not \"I''ll be more careful.\""}],"minChars":700,"calibration":[{"key":"conversation2","label":"Conversation 2 prediction — % chance it invented something","hint":"Recorded before you check — honesty is what''s scored, not accuracy.","placeholder":"e.g. 60","min":0,"max":100}],"submitLabel":"Three conversations + reflection","intro":"Paste your three conversation accounts and the reflection below. Resubmission is free and unlimited — the score is a mirror, not a gate."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-knowledge_check', 'ai101-m1', 'knowledge_check', '{"title":"Knowledge check — 10 questions","note":"Retakes are free and unlimited; previous answers are cleared.","reviewedAt":"2026-07-28","questions":[{"id":"q1","prompt":"Which is the most accurate working definition of \"AI\" as the term is used in your day-to-day work?","options":["A category covering many technologies, most prominently large language models","Software built to replace human workers across knowledge-work roles","Any program that automates a task, including spreadsheet macros and scheduling rules","A system that has achieved human-like general awareness"],"correctIndex":0,"explanation":"AI is best understood as a broad category, with LLMs the kind most directly reshaping knowledge work. The others miss differently: human-like awareness is science fiction rather than anything the field has produced; calling all automation AI is so broad it stops being useful (a calculator isn''t AI); and \"built to replace workers\" is a claim about intent, not a definition."},{"id":"q2","prompt":"What does a large language model actually do when you send it a prompt?","options":["Looks up an answer in a database of pre-written responses","Searches the internet and summarizes the top results","Predicts what text should come next, one small piece at a time, from patterns learned in training","Reasons through the problem as a human expert would, then writes out the solution"],"correctIndex":2,"explanation":"The core mechanic is next-piece prediction. Some tools layer search on top, which changes what''s available in the prompt, but the model underneath is a statistical text predictor — not a lookup, not a search engine, and not human-style reasoning, even when the output resembles it."},{"id":"q3","prompt":"Your ATS advertises \"AI-powered candidate matching.\" Based on this module, what''s the most useful first question to ask the vendor?","options":["Which large language model does it use?","Is this a language model or a scoring/matching model, and does it influence a decision about a person?","How large is the context window?","What was the knowledge cutoff date?"],"correctIndex":1,"explanation":"Candidate matching is usually a scoring model, not a language model — and scoring models that influence employment decisions are where regulatory obligations and adverse-impact risk concentrate. The other three questions are only meaningful once you know it''s a language model, and asking them first signals you haven''t made the distinction."},{"id":"q4","prompt":"You ask the same question twice and get two slightly different answers. Most likely explanation?","options":["One of the two is a malfunction","The provider updated the model between your questions","A bug worth reporting to support","There''s a small amount of randomness in how each next piece is chosen, which is normal"],"correctIndex":3,"explanation":"Small variation is built into how these systems generate output. The same input rarely produces byte-identical results, and sometimes the second attempt is better — which is why re-running a prompt is a legitimate technique rather than a workaround."},{"id":"q5","prompt":"What is the context window?","options":["The hours during which the tool is available","Your organization''s list of approved use cases","How much text the model can hold in view at once: your message, the conversation, and attachments","The interface around the chat box"],"correctIndex":2,"explanation":"It''s the model''s working memory for a given response, and it''s finite. Understanding it explains why very long conversations feel like the model forgot something, and why pasting in a 90-page handbook can crowd out the question you actually asked."},{"id":"q6","prompt":"You ask an AI what your organization''s bereavement leave policy says. You paste nothing. What''s most likely?","options":["It produces a fluent, specific, plausible policy that isn''t yours","It refuses and explains it has no access to your systems","It asks a series of clarifying questions before answering","It accurately describes typical policy and clearly labels it as generic"],"correctIndex":0,"explanation":"This is the highest-stakes pattern in the module. The model never saw your handbook, but it has seen thousands of bereavement policies, so it can generate something that reads exactly like one. Some tools will hedge — the other outcomes happen sometimes — but you cannot rely on it, and the failure is quiet. You get a real-looking answer with no signal that it''s invented."},{"id":"q7","prompt":"Which of these is NOT shaped by a model''s training data?","options":["Which languages it''s strongest in","Which topics it handles well","Whether it knows about something that happened this morning","The exact wording you choose to put in your prompt"],"correctIndex":3,"explanation":"Your prompt is the data *you* contribute, in the moment. It''s the part you control and the part not inherited from training. The other three — topic strength, language strength, recency — all follow directly from what was in the training corpus and when it was assembled."},{"id":"q8","prompt":"Why does the bias question carry more weight in People work than in most functions?","options":["HR teams use AI more heavily than other functions","Models are trained on more HR data than other kinds","Outputs can influence decisions about people, which is the mechanism by which adverse impact occurs","Employment law prohibits using AI in HR contexts"],"correctIndex":2,"explanation":"All training data carries bias and all models can reproduce it. What changes in People work is the consequence: when a biased output shapes screening, evaluation, or advancement, the harm attaches to a person and creates real legal exposure. The last option is simply false — AI isn''t prohibited in HR, it''s regulated in specific decision contexts."},{"id":"q9","prompt":"What''s the most accurate description of a hallucination?","options":["The model deliberately misleading you","The model producing something confident and plausible that is wrong or invented","The model flagging uncertainty in its response","The model crashing or returning nothing"],"correctIndex":1,"explanation":"Note what''s absent: intent. The model isn''t lying, because lying requires knowing the truth and choosing otherwise. It''s generating statistically likely text, and sometimes likely text is false. That''s precisely why it''s hard to catch — there''s no tell."},{"id":"q10","prompt":"You want to start using AI well. Based on this module, which habit is most important to build first?","options":["Asking, before any task: what does the model not know that I''d need to give it?","Always writing the longest, most detailed prompt possible","Using AI for as many tasks as you can each day to build reps","Keeping track of which model versions each provider has released"],"correctIndex":0,"explanation":"That single question is the seed of good prompting and of good delegation judgment. It forces you to think about the data the model needs — the single largest lever on output quality — and it surfaces the tasks you shouldn''t hand over at all. The others are counterproductive (longer isn''t better), unfocused (reps without judgment build confident bad habits), or performative (version numbers are trivia)."}]}', '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-calibration-prompt-before-you-start-10', 'ai201-m1', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One question, thirty seconds. You''ll come back to it at the end of the course.*

Think of the recurring task you would most like to hand to AI.

**How many hours a month does it actually cost you right now?**

Write the number down. Most practitioners discover in Module 7 that their estimate was off by
half — in one direction or the other — and the direction says a lot about which workflows they
should build first.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-module-brief-20', 'ai201-m1', 20, 'prose', 'stable', '## Module brief

You finished 101, which means you can do something most of your peers can''t: predict what an AI
tool will do well before you ask, brief it properly when you do, and catch it when it''s
confidently wrong. That''s real fluency. And if you''re honest about your week since then, you''ve
probably noticed something irritating about it.

Everything you do with AI, you do by hand, from scratch, every time.

You re-explain your company''s voice before every draft. You re-describe what a good interview
debrief looks like every Thursday. The survey summary that took ninety minutes in March took
ninety minutes again in June, because nothing you learned in March was written down anywhere the
tool could see. You''ve become a skilled artisan working without a workshop — every piece
handmade, quality depending on your energy that day, nothing repeatable, nothing you could hand
to anyone else.

The jump from Novice to Practitioner is not learning more about AI. It''s the jump from **tasks to
systems**: from "I used AI for this" to "this runs every week, the same way, with checks built
in, and I could show a colleague how." That jump is what this course is for, and it starts with a
change of lens, not a change of tools.

**One build, eight modules.** At the end of this module you will choose a single workflow from
your own week and write its spec. Every module that follows advances that same build: its context
pack in M2, its pipeline in M3, its verification design in M4, and so on until M8, where you run
it for real and prove what it saved. Choose like it matters, because you''ll be living with this
choice for a while. The good news: this module''s whole job is teaching you how to choose.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-learning-objectives-30', 'ai201-m1', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Name the five parts every repeatable workflow has, and find them in a task you already do.
2. Audit your own week and surface the tasks that earn the workflow treatment.
3. Apply the selection rules — and explain why "most annoying" and "highest stakes" are both
   wrong answers for a first build.
4. Write a five-part workflow spec concrete enough that a colleague could challenge it.
5. State the practitioner''s extension of the delegation heuristic from memory.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-lesson-1-the-anatomy-40', 'ai201-m1', 40, 'prose', 'stable', '## Lesson 1 · The anatomy

Every repeatable workflow has the same five parts. Not because a framework says so, but because
when any part is missing, the thing stops being a workflow and goes back to being an improvisation.

**Trigger.** What makes it run: a day of the week, an event ("interviews finished"), an arrival
("survey closed," "notes exist"). If you can''t name the trigger, you don''t have a workflow — you
have a task you sometimes remember.

**Inputs.** The material you supply, and where it lives. 101''s central lesson — the model knows
only what you give it — becomes an inventory question here: *which documents, in which state, from
where?* Vague inputs are where workflows quietly die.

**Transformation.** What the model actually does: summarize, restructure, draft variants,
translate registers, extract themes. One transformation per step. If you find yourself writing
"and then it also decides…" — stop. That''s not a transformation, and Lesson 3 has words for you.

**Verification.** Who or what checks the output, how, and against what standard — *before* it
reaches anyone it could affect. In most people''s implicit workflows this part simply doesn''t
exist, which is why it gets its own module (M4) and a hard rule: you may not automate what you
can''t verify.

**Output and owner.** What leaves the workflow, in what format, and — non-negotiable — the one
human whose name is on it. An output nobody owns is an incident that hasn''t happened yet.

Here''s the useful part: every recurring task you already do with AI has these five parts
*implicitly*. Drawing them out doesn''t add bureaucracy; it exposes which part was always missing.
It''s almost always verification. Sometimes it''s the trigger — which is why the task happens in
March and then not again until someone''s embarrassed in June.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-try-50', 'ai201-m1', 50, 'try_this', 'stable', '### Try this — 3 minutes
Take the last thing you used AI for at work. Any task, however small.

1. Name its five parts out loud: trigger, inputs, transformation, verification, output/owner.
2. Notice which one you can''t name crisply.
3. Ask: if this ran next month without you remembering March, what would break?

That missing part is not a personal failing. It''s the difference between artisan work and a
system, and it''s exactly what this course builds.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-lesson-2-the-audit-60', 'ai201-m1', 60, 'prose', 'stable', '## Lesson 2 · The audit

You can''t choose a first build from memory, because memory surfaces the *loudest* task, not the
best candidate. The audit is a structured pass over your actual week, and it takes twenty minutes.

Pull up last week''s calendar and sent mail. List every task that meets all three of these:

- **It recurs.** Weekly, monthly, per-event — but on a rhythm. One-offs, however painful, don''t
  make the list.
- **It has a shape.** The same kind of input goes in and the same kind of output comes out, every
  time. If each occurrence is genuinely different, it''s not structured — it''s a series of
  judgment calls that happen to recur.
- **You supply the material.** The inputs exist and you control them: your notes, your data
  export, your policy text. If the task needs knowledge nobody has written down, 101 told you
  exactly what the model will do with that gap — fill it, fluently, from nothing.

For each task that survives, score two more things, low/medium/high:

- **Stakes.** What happens if a bad version ships? A clumsy newsletter is low. Anything that
  touches a named person''s pay, performance, or employment is high — and flagged for a different
  conversation entirely.
- **Current cost.** Honest hours per month. Not how much you resent it — how long it takes.

Most People leaders'' audits surface the same families: interview notes → debriefs, survey
verbatims → themes, policy text → plain-language versions, data exports → narrative summaries,
bullet points → recurring communications. Yours will have its own shape, but expect between five
and ten survivors. That''s your candidate pool — you only need one.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-try-70', 'ai201-m1', 70, 'try_this', 'stable', '### Try this — the audit itself, 20 minutes
Do the real thing, now if you can:

1. Open last week''s calendar and sent mail. List recurring tasks — aim past ten before you judge
   any of them.
2. Strike everything that fails the three tests: recurs, has a shape, you supply the material.
3. Score survivors for stakes and honest monthly cost.
4. Circle the three with the best cost-to-stakes ratio.

Keep the list. The sorting exercise below will sharpen your instincts before you commit to one.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-lesson-3-the-selection-rules-80', 'ai201-m1', 80, 'prose', 'stable', '## Lesson 3 · The selection rules

You have candidates. Here is how practitioners choose — and the two seductive wrong answers to
refuse.

**Wrong answer one: the most annoying task.** Annoyance measures how you feel, not whether the
task can be systematized. The task you hate most is often hateful precisely *because* it resists
structure — every instance different, inputs scattered, judgment throughout. A first build there
fights the structure problem and the learning problem at the same time.

**Wrong answer two: the highest-stakes task.** The logic seems noble — "if I''m going to invest,
invest where it matters most." But your first workflow is where you''ll make your learning
mistakes, and high-stakes work is where mistakes cost the most and verification is hardest to
design. You don''t learn to drive on the motorway.

**The right first build scores like this:**

- **High frequency** — it runs at least weekly, so feedback comes fast and time savings compound.
- **High structure** — same shape in, same shape out, so the transformation stays simple.
- **You own the inputs** — no waiting on other people''s data or undocumented knowledge.
- **Low-to-medium stakes** — a bad output embarrasses nobody and harms nobody while you learn.

Boring is a feature. The interview-notes debrief and the bullet-points newsletter are unglamorous
and perfect. Your first build''s job is not to impress anyone; it''s to teach you the anatomy on
something that can''t hurt you, so your *second* build — the one with real leverage — inherits
working habits instead of hopeful ones.

And one boundary, before the exercise makes it concrete. 101 gave you the delegation heuristic;
201 extends it one level up, and this is the course''s spine:

> **You may only systematize what you have verified by hand. And a workflow, like a model, must
> not make decisions about people — automation makes decisions faster, not fairer.**

The second sentence has teeth that surprise people. A workflow that *drafts* a rejection email
transforms material. A workflow that decides *who gets one* has crossed the line, no matter how
good the model is, and "a human clicks approve" doesn''t move the line back if the human stopped
reading. The gray zone — decision-support whose default quietly becomes the decision — gets its
own test in M5. For now the plain rule shapes which tasks are even candidates.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-sort', 'ai201-m1', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Sorting exercise \u2014 Workflow it, keep it manual, or never?", "intro": "Ten minutes. Twelve tasks from a People leader''s real week. Sort each into **workflow it**, **keep it manual**, or **never systematize**.\n\nThe pattern the key will show you, stated in advance so you can test it as you sort: workflow the recurring transformations of material you own. Keep manual the judgment calls that happen to recur \u2014 and anything that happens once. Never systematize decisions about people.\n\nNothing reveals until all twelve are committed."}', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-key-takeaways-90', 'ai201-m1', 90, 'takeaways', 'stable', '## Key takeaways

- **Fluency isn''t practice.** 101 taught you to use AI well; nothing about using it well makes it
  repeatable. That''s a different skill, and it''s a systems skill.
- **Five parts, always:** trigger, inputs, transformation, verification, output-with-owner. The
  part you can''t name is the part that fails in June.
- **Audit, don''t remember.** Memory nominates the loudest task; the calendar and sent mail
  nominate the true candidates.
- **First build: high frequency, high structure, owned inputs, low stakes.** Boring is a feature.
  The impressive build comes second, and inherits working habits.
- **The practitioner''s heuristic:** only systematize what you''ve verified by hand — and a
  workflow must not make decisions about people. Automation makes decisions faster, not fairer.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-activity-link', 'ai201-m1', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Capstone stage 1 \u2014 Pick it and spec it", "blurb": "Choose one workflow from your audit and write its five-part spec: trigger, inputs, transformation, verification, output and owner. Two predictions first; AI-graded against the module rubric. This spec is the artifact every later module builds on.", "estMinutes": "20\u201325"}', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-sources-and-attribution-110', 'ai201-m1', 110, 'prose', 'stable', '## Sources and attribution

Builds directly on AI 101 Module 1 (delegation heuristic, training-data bias, vendor questions)
and Module 6 (verification habits). Workflow anatomy synthesized for this course; the
selection-rule framing (frequency × structure × ownership × stakes) is original to the course.
*Cross-references to be verified against the final 101 module numbering before publication.*', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-activity-capstone-stage-1-pick-it-and-spec-it-10', 'ai201-m1-activity', 10, 'prose', 'stable', '## Capstone stage 1 · Pick it and spec it

This is the module''s applied activity, and the first artifact of your eight-module build.

**Choose one workflow** from your audit — the selection rules are your guide, and "boring but
weekly" beats "impressive but quarterly."

**Predict first, two numbers.** Before writing the spec, record: (1) honest hours per month the
task costs you today; (2) the percentage of that time you expect the workflow to save within a
month of shipping. As with everything calibration in this course, you''re graded on honesty and
specificity, never on being right.

**Write the five-part spec:**

- **Trigger** — what makes it run, concretely enough to schedule.
- **Inputs** — each source of material, where it lives, and what state it arrives in.
- **Transformation** — what the model does, as verbs. One transformation per step; if you need
  three steps, say so.
- **Verification** — how you''ll check output before it ships, even roughly. "I read all of it"
  is legitimate at this stage; M4 will make it cheaper. A blank here is the one thing the spec
  can''t survive.
- **Output and owner** — format, destination, and the named human accountable. (That''s you. Write
  it anyway. It matters in M8, when someone else runs this.)

**Then defend the choice** in a paragraph: why this one, against the selection rules — frequency,
structure, input ownership, stakes. If you rejected a more tempting candidate, say which and why.
That reasoning is worth more than the spec itself.

**[V]** Where to keep it: start a dedicated Claude Project for your build and put the spec in its
knowledge. Every module from M2 on adds to that same Project — by M8 it will contain your whole
workflow. If your organization uses a different provisioned tool, your deployment''s lab track
shows the equivalent home.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Spec concreteness** | All five parts present and specific enough that a colleague could challenge them. Inputs name real sources; the transformation is verbs, not vibes. |
| **Selection reasoning** | The choice is defended against the selection rules, honestly scored for frequency, structure, ownership, and stakes — including what was rejected and why. |
| **Verification exists** | The verification part is present and matched to stakes. It can be modest; it cannot be missing or hand-waved. |
| **Calibration** | Both predictions recorded before the spec, with enough specificity to score in M7. Honesty and precision graded; accuracy never. |', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-micro-core', 'ai201-m1-micro', 10, 'prose', 'stable', '## Module 1 in two minutes

**Fluency isn''t practice.** 101 taught you to use AI well; nothing about using it well makes it repeatable. Everything you do with AI is still handmade — context retyped, quality varying with your energy, nothing a colleague could run. The Practitioner''s jump is from tasks to systems.

**Every repeatable workflow has five parts:** trigger, inputs, transformation, verification, output-with-owner. Your recurring tasks already have these parts implicitly; drawing them out exposes which one is missing. It''s almost always verification.

**Audit, don''t remember.** Memory nominates the loudest task; last week''s calendar and sent mail nominate the true candidates. A candidate must recur, have a shape, and run on material you supply.

**Your first build: high frequency, high structure, owned inputs, low stakes.** Not the most annoying task (annoyance often means the task resists structure) and not the highest-stakes one (you''ll make your learning mistakes on it). Boring is a feature — the impressive build comes second, and inherits working habits.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-micro-heuristic', 'ai201-m1-micro', 20, 'callout', 'stable', '### The practitioner''s heuristic

You may only systematize what you have verified by hand. And a workflow, like a model, must not make decisions about people — automation makes decisions faster, not fairer.', NULL, '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at) VALUES ('ai201-m1-micro-close', 'ai201-m1-micro', 30, 'prose', 'stable', '**The full module adds** the audit method, the selection rules with their two seductive wrong answers, a twelve-task sorting exercise from a People leader''s real week, and the capstone''s first stage: choosing your build and writing its five-part spec — the artifact all seven later modules advance.', NULL, '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-sorting', 'ai201-m1', 'sorting', '{"buckets":[{"id":"workflow","label":"Workflow it","hint":"Recurring transformation of material you own","rank":2,"pct":85},{"id":"manual","label":"Keep it manual","hint":"Judgment-heavy, or a true one-off","rank":1,"pct":50},{"id":"never","label":"Never systematize","hint":"Decisions about people","rank":0,"pct":15}],"tasks":[{"id":"t1","text":"Turning each week''s interview notes into structured debriefs","key":"workflow","reasoning":"The canonical first build: weekly, structured, your notes."},{"id":"t2","text":"Drafting the monthly people-metrics narrative from a data export you own","key":"workflow","reasoning":"Your export, same shape monthly; verification catches the numbers."},{"id":"t3","text":"Deciding which of two finalists receives the offer","key":"never","reasoning":"A decision about a person. It isn''t about capability, and it doesn''t move for better models."},{"id":"t4","text":"Refreshing job postings each quarter to strip jargon and drift","key":"workflow","reasoning":"Quarterly but perfectly structured — pure transformation."},{"id":"t5","text":"Responding to an employee''s grievance email","key":"manual","reasoning":"Arrives on a rhythm, but each one is a distinct human situation carrying legal weight. AI can help you understand a policy; the response is authored, not generated."},{"id":"t6","text":"Summarizing exit-interview verbatims at quarter end","key":"workflow","reasoning":"Same pattern as engagement summaries — with the same caveat: read the raw comments too."},{"id":"t7","text":"Setting performance ratings ahead of calibration","key":"never","reasoning":"The decision where bias stops being abstract: automation reproduces patterns at scale and speed, and adverse impact is the mechanism."},{"id":"t8","text":"Drafting the weekly HR newsletter from bullet points you supply","key":"workflow","reasoning":"Low stakes, weekly, you supply every bullet."},{"id":"t9","text":"Writing this year''s reduction-in-force communication","key":"manual","reasoning":"A one-off, and one of the highest-stakes documents you''ll ever write. Fails the ''recurs'' test before stakes even enter it."},{"id":"t10","text":"Translating policy updates into plain-language change notes","key":"workflow","reasoning":"Text in, plainer text out."},{"id":"t11","text":"Screening résumés for a hard-to-fill role","key":"never","reasoning":"A decision about people — and the place your vendors quietly systematize it for you. You wrote the questions to ask them in 101."},{"id":"t12","text":"Preparing talking points for a sensitive conversation with a specific employee","key":"manual","reasoning":"The material that matters — history, relationship, what you know that isn''t written down — is exactly what no system holds."}],"pattern":"Workflow the recurring transformations of material you own. Keep manual the judgment calls that happen to recur — and anything that happens once. Never systematize decisions about people.","postscript":"If you missed several, look at which kind. Putting judgment calls in ''workflow it'' means you''ll build something that launders discretion through a template. Putting good transformations in ''keep it manual'' means the artisan tax continues for no reason. Both are fixable; that''s what the selection rules are for."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-rubric', 'ai201-m1', 'rubric', '{"promptVersion":"ai201-m1-spec-v1","moduleId":"ai201-m1","minChars":600,"submitLabel":"The five-part spec + your selection reasoning","intro":"Write the five-part spec — trigger, inputs, transformation, verification, output and owner — then defend the choice against the selection rules, including what you rejected and why. Resubmission is free and unlimited.","activityContext":"The learner is submitting Capstone Stage 1 of AI 201: a five-part workflow spec (trigger, inputs, transformation, verification, output/owner) for one workflow chosen from an audit of their own week, plus a paragraph defending the selection against the module''s rules (high frequency, high structure, owned inputs, low-to-medium stakes).","calibration":[{"key":"hours","label":"Prediction 1 — hours/month this task costs you today","hint":"Honest hours, not resentment. Scored for honesty in Module 7.","placeholder":"e.g. 6","min":0,"max":200},{"key":"savings","label":"Prediction 2 — % of that time the workflow saves within a month","hint":"Recorded before you build. Direction of error is the lesson.","placeholder":"e.g. 50","min":0,"max":100}],"dimensions":[{"name":"Spec concreteness","criteria":"All five parts present and specific enough that a colleague could challenge them. Inputs name real sources; the transformation is verbs, not vibes."},{"name":"Selection reasoning","criteria":"The choice is defended against the selection rules, honestly scored for frequency, structure, ownership, and stakes — including what was rejected and why."},{"name":"Verification exists","criteria":"The verification part is present and matched to stakes. It can be modest; it cannot be missing or hand-waved."},{"name":"Calibration","criteria":"Both predictions recorded before the spec, with enough specificity to score in Module 7. Honesty and precision graded; accuracy never."}]}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-knowledge_check', 'ai201-m1', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone spec is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"What most reliably separates a workflow from a one-off AI task?","options":["It uses a more capable model","It has a named trigger, and runs the same way without you re-inventing it each time","It saves more than an hour a week","It involves more than one prompt"],"correctIndex":1,"explanation":"The anatomy is the definition: a trigger and a repeatable shape. Model choice, time saved, and prompt count are all properties a workflow *might* have; the trigger and the sameness are what make it one."},{"id":"q2","prompt":"Which part of the anatomy is most often missing from people''s implicit workflows?","options":["The trigger","The inputs","Verification","The output format"],"correctIndex":2,"explanation":"Almost everyone has an intuitive trigger, inputs, and output. Almost nobody has designed the checking step — which is why it gets its own module and why the spec cannot ship without it."},{"id":"q3","prompt":"Why is \"the task that annoys me most\" a poor basis for a first build?","options":["Annoying tasks are usually someone else''s responsibility","Annoyance often signals the task resists structure — each instance different, judgment throughout","First builds should target the highest-stakes work instead","It isn''t — high annoyance is a good proxy for high value"],"correctIndex":1,"explanation":"The tasks that grate hardest often do so *because* they won''t routinize. And C is the other seductive wrong answer: high stakes belong with your second build, after the habits work."},{"id":"q4","prompt":"A workflow drafts rejection emails from your notes on each candidate. Another selects which candidates receive them. Under the practitioner''s heuristic:","options":["Both are acceptable if a human clicks approve","Neither is acceptable in People work","The first transforms material you supply; the second makes a decision about people, and stays with a human","Both are acceptable once the model is accurate enough"],"correctIndex":2,"explanation":"Drafting is transformation — the center of the model''s competence. Selection is a decision about a person, and the heuristic''s second sentence doesn''t bend for accuracy (D) or for a rubber-stamp click (A) if the human has stopped genuinely deciding."},{"id":"q5","prompt":"What makes \"you supply the material\" a hard requirement for a workflow candidate?","options":["Supplied material is cheaper to process","Without it, the model fills the gap with fluent invention — 101''s central failure mode, now on a schedule","It''s a data-privacy requirement","It keeps the context window small"],"correctIndex":1,"explanation":"A one-off hallucination is an error; a scheduled workflow built on missing inputs is an error *generator*. The audit''s third test exists to catch this before you build on it."},{"id":"q6","prompt":"Your first build should score:","options":["High frequency, high structure, owned inputs, low-to-medium stakes","High stakes, high visibility — invest where it matters most","Low frequency, so mistakes surface slowly","Whatever your manager most wants automated"],"correctIndex":0,"explanation":"Fast feedback, simple transformation, no dependency on others'' data, and mistakes that can''t hurt anyone while you learn. The high-stakes build is the second one."},{"id":"q7","prompt":"The audit uses last week''s calendar and sent mail rather than your recollection because:","options":["Memory surfaces the loudest task, not the best candidate","Calendars record time more precisely","It produces documentation for your manager","Sent mail shows which tasks involve other people"],"correctIndex":0,"explanation":"The point is candidate *selection*, and recollection is biased toward recency and resentment. The paper trail is flatter and more honest."},{"id":"q8","prompt":"\"A workflow, like a model, must not make decisions about people.\" The strongest reason, from this course:","options":["Regulation prohibits all AI involvement in HR decisions","Models aren''t yet accurate enough for employment decisions","Automation reproduces bias patterns at scale and speed — adverse impact''s mechanism — and accuracy doesn''t cure it","Employees prefer decisions made by humans"],"correctIndex":2,"explanation":"A is false (regulation targets specific decision contexts, as 101 covered), and B fails because the rule survives arbitrary accuracy: the issue is what a decision *is*, not how well a system scores. D may be true but is not the mechanism."}]}', '2026-08-07');
